+
+	const { agents, agentsLoaded, selectedAgentId } = useSelect(
+		( select ) => ( {
+			agents: select( STORE_NAME ).getAgents(),
+			agentsLoaded: select( STORE_NAME ).getAgentsLoaded(),
+			selectedAgentId: select( STORE_NAME ).getSelectedAgentId(),
+		} ),
