+		const sseBody = [
+			'event: token',
+			`data: ${ JSON.stringify( { token: 'Hello from the AI!' } ) }`,
+			'',
+			'event: done',
+			`data: ${ JSON.stringify( { session_id: sessionId } ) }`,
+			'',
+			'',
+		].join( '\n' );
