+					'Content-Type'  => 'application/json',
+					'X-API-Key'     => $api_key,
+					'anthropic-version' => '2023-06-01',
+				),
+				'body'    => (string) wp_json_encode(
+					array(
+						'model'     => $model_id,
+						'max_tokens' => 10,
+						'messages'  => array(
+							array( 'role' => 'user', 'content' => $prompt ),
