+	private static function call_google( string $model_id, string $prompt ) {
+		$api_key = Settings::get_provider_key( 'google' );
+		if ( empty( $api_key ) ) {
+			return new \WP_Error(
+				'benchmark_no_google_key',
+				__( 'Google API key not configured.', 'gratis-ai-agent' )
+			);
