+
+use GratisAiAgent\REST\BenchmarkController;
+use WP_REST_Request;
+use WP_REST_Server;
+use WP_UnitTestCase;
+
+/**
+ * Integration tests for BenchmarkController.
+ *
+ * @group benchmark
+ * @group rest
+ */
+class BenchmarkControllerTest extends WP_UnitTestCase {
+
+	/**
+	 * REST server instance.
+	 *
+	 * @var WP_REST_Server
+	 */
+	protected WP_REST_Server $server;
+
